class Solution {
public:
    long long minCost(int m, int n, vector<vector<int>>& waitCost) {
        const long long INF = (1LL << 60);
        vector<long long> dp(n, INF);
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i == 0 && j == 0) {
                    dp[j] = 1;
                    continue;
                }
                long long best = INF;
                if (i > 0) best = min(best, dp[j] + ((i == 1 && j == 0) ? 0 : waitCost[i - 1][j]));
                if (j > 0) best = min(best, dp[j - 1] + ((i == 0 && j == 1) ? 0 : waitCost[i][j - 1]));
                dp[j] = best + 1LL * (i + 1) * (j + 1);
            }
        }
        return dp[n - 1];
    }
};
